 if((Get-FileHash $schema -Algorithm SHA256).Hash.ToLowerInvariant() -ne '24765f818899517aaaa79e39fe7269aae201bcaf774ea4faeff3a8948327ce06'){throw 'Baseline checksum mismatch.'}
 $bootstrapFiles=Join-Path $clean 'sql\bootstrap-prerequisites-20261016'
