 foreach($entry in $review.sourceHashes){$file=Join-Path $project $entry.file;if(-not(Test-Path $file)){throw "Reviewed file missing: $($entry.file)"};if((Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Source changed since readiness review: $($entry.file)"}}
