 foreach($name in @('auth.module.ts','mfa-crypto.ts','mfa-lab.service.ts','mfa-lab.controller.ts','mfa-lab.spec.ts','recovery-lab.service.ts','recovery-lab.controller.ts','recovery-lab.spec.ts','auth-audit.service.ts','auth-audit.controller.ts','auth-audit.spec.ts')){Copy-Item (Join-Path $payload $name) (Join-Path $clean ('src\auth\'+$name)) -Force}
 foreach($screen in @('recovery-lab','mfa-lab','auth-audit')){
  New-Item -ItemType Directory -Path (Join-Path $clean ('web\'+$screen)) -Force | Out-Null
  foreach($name in @('index.html','app.js','style.css')){$from=$name;if($screen -eq 'mfa-lab'){$from='mfa-'+$name};if($screen -eq 'recovery-lab'){$from='recovery-'+$name};Copy-Item (Join-Path $payload $from) (Join-Path $clean ('web\'+$screen+'\'+$name)) -Force}
 }
 foreach($name in @('index.html','app.js','style.css')){Copy-Item (Join-Path $project ('web\account-sessions\'+$name)) (Join-Path $clean ('web\account-sessions\'+$name)) -Force}
 $migrationDir=Join-Path $clean 'sql\migrations'
 Copy-Item (Join-Path $project 'sql\migrations\*') $migrationDir -Force
 $manifestPath=Join-Path $migrationDir 'manifest.json'
 $manifest=Get-Content $manifestPath -Raw | ConvertFrom-Json
 if($manifest.migrations.Count -ne 3 -or $manifest.migrations[2].id -ne '0004_password_change'){throw 'Unexpected approved working migration history.'}
 foreach($item in @(@{id='0005_account_recovery_lab';position=5},@{id='0006_mfa_lab';position=6},@{id='0007_auth_audit_lab';position=7})){
