  if($item.Name -match '^(PG|GYMPRO_|PRISMA_|.*DATABASE_URL$|NODE_OPTIONS$)'){[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}
 }
 $env:PGSSLMODE='disable'
