 $common=@('-X','-q','-w','-h','127.0.0.1','-p',"$port",'-U','postgres','-d',$target,'-v','ON_ERROR_STOP=1','-v',"target=$target")
 Run (Join-Path $bin 'psql.exe') ($common+@('-f',(Join-Path $bootstrapFiles '000-roles.sql'))) 'roles'
