 }
 function Read-RehearsalPassword([string]$Prompt){while($true){$secure=Read-Host $Prompt -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);try{$value=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$secure.Dispose()};if($value.Length -ge 12 -and $value.Length -le 200 -and -not [string]::IsNullOrWhiteSpace($value)){return $value};$value=$null;Write-Host 'Use 12 to 200 characters.' -ForegroundColor Yellow}}
 $env:GYMPRO_1F_PASSWORD=Read-RehearsalPassword 'Choose a separate temporary account password (12-200 characters)'
 $env:GYMPRO_RECOVERY_INBOX_PASSWORD=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N')

 try {Run $node @((Join-Path $payload 'verify-and-demo.mjs'),$clean,"$port",$target,"$apiPort",$report) 'clean-startup-login-e2e'} finally {$env:GYMPRO_1F_PASSWORD=$null;$env:GYMPRO_RECOVERY_INBOX_PASSWORD=$null}
 $results=Get-Content (Join-Path $report 'provisioning-results.json') -Raw | ConvertFrom-Json
 $e2e=Get-Content (Join-Path $report 'root-e2e-results.json') -Raw | ConvertFrom-Json
 if($results.automaticChecksPassed -ne $true -or $results.automaticCheckCount -ne 119 -or $results.fixtureCleanupPassed -ne $true -or $results.ownApiStopped -ne $true -or $e2e.success -ne $true){throw 'Verification or cleanup evidence incomplete.'}
 $success=$true
} catch {$failure=$_.Exception.Message;Write-Host ('FAIL: '+$failure) -ForegroundColor Red} finally {
 $env:GYMPRO_1F_PASSWORD=$null;$env:GYMPRO_RECOVERY_INBOX_PASSWORD=$null
 if($started -and (Test-Path (Join-Path $cluster 'postmaster.pid'))){try{Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-m','fast','-w','stop') 'stop'}catch{$success=$false;$failure=$_.Exception.Message;Write-Host ('FAIL: '+$failure) -ForegroundColor Red}}
}
if($success){
 try{
  $suite=Get-Content (Join-Path $report 'full-suite-results.json') -Raw | ConvertFrom-Json
  $saved=Join-Path $project 'tools\auth-audit-lab';New-Item -ItemType Directory -Path $saved -Force | Out-Null
  foreach($name in @('0007_auth_audit_lab.sql','auth.module.ts','auth-audit.service.ts','auth-audit.controller.ts','auth-audit.spec.ts','index.html','app.js','style.css','verify-and-demo.mjs','README.md')){Copy-Item (Join-Path $payload $name) (Join-Path $saved $name) -Force}
  Copy-Item $PSCommandPath (Join-Path $project 'scripts\completion-auth-audit-lab.ps1') -Force
  [ordered]@{scope='Isolated authentication audit history';fullSuitePassed=$true;passedTests=$suite.numPassedTests;skippedTests=$suite.numPendingTests;rootE2ePassed=$true;httpDatabaseChecks=119;auditSpecificChecks=20;atomicSuccessAuditVerified=$true;privateRejectedLoginVerified=$true;selfTenantScopeVerified=$true;paginationVerified=$true;runtimeMutationDenied=$true;fixturesRemoved=$true;ownApiStopped=$true;clusterStopped=$true;browserAcceptance='pending-user-confirmation';workingDatabaseChanged=$false;productionAppSourceChanged=$false;workingEnvironmentChanged=$false;productionAuditEnabled=$false;kbzPayDeferred=$true;reportFolder=$report;verifiedAt=(Get-Date -Format o)} | ConvertTo-Json | Set-Content (Join-Path $report 'auth-audit-lab-summary.json') -Encoding UTF8
  Copy-Item (Join-Path $report 'auth-audit-lab-summary.json') (Join-Path $project 'docs\completion\auth-audit-lab-summary.json') -Force
